"""Собирает HTML-концепты портфолио (portfolio/*.html) из данных ниже.
Скриншоты для блока «Примеры работ» снимает tools/shoot_concepts.js."""
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "portfolio"

def svg(body, bg=None, vb="0 0 600 520"):
    return f'<svg viewBox="{vb}" preserveAspectRatio="xMidYMid slice" aria-hidden="true">{body}</svg>'

# ---------- Иллюстрации (v — вариант для карточек каталога) ----------
def art_realty(v=0):
    hs = [(40,260,90),(150,150,110),(280,90,120),(420,190,100),(520,240,90)]
    if v: hs = [(x, y + (v * 37 % 70) - 20, w) for x, y, w in hs]
    out = '<defs><linearGradient id="sk" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c9d6f2"/><stop offset="1" stop-color="#f3efe6"/></linearGradient></defs><rect width="600" height="520" fill="url(#sk)"/><circle cx="470" cy="110" r="46" fill="#f7d9a0"/>'
    for i, (x, y, w) in enumerate(hs):
        c = ["#22325e", "#2e4278", "#1b2850", "#34497f", "#283a6b"][i]
        out += f'<rect x="{x}" y="{y}" width="{w}" height="{520-y}" fill="{c}"/>'
        for yy in range(y + 18, 470, 26):
            for xx in range(x + 12, x + w - 14, 22):
                lit = (xx * 7 + yy * 3 + v) % 5 == 0
                out += f'<rect x="{xx}" y="{yy}" width="10" height="13" fill="{"#f3c76b" if lit else "#4a5f99"}"/>'
    out += '<rect y="470" width="600" height="50" fill="#9db48a"/>'
    for x in (60, 130, 360, 470, 560):
        out += f'<circle cx="{x}" cy="462" r="24" fill="#5f8a55"/><rect x="{x-3}" y="470" width="6" height="22" fill="#5a4636"/>'
    return out

def art_doma(v=0):
    roof = ["#7a3b2e", "#3d4a5c", "#5b3a29"][v % 3]
    wall = ["#efe4d2", "#dcd6cc", "#e9dcc7"][v % 3]
    out = '<defs><linearGradient id="sk2" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#cfe3ec"/><stop offset="1" stop-color="#f2efe4"/></linearGradient></defs><rect width="600" height="520" fill="url(#sk2)"/>'
    out += '<path d="M0 380 Q150 340 300 370 T600 360 V520 H0z" fill="#a9c58f"/><path d="M0 420 Q200 390 600 420 V520 H0z" fill="#88ad6f"/>'
    out += f'<rect x="150" y="240" width="300" height="180" fill="{wall}"/><polygon points="130,248 300,130 470,248" fill="{roof}"/><rect x="380" y="150" width="26" height="60" fill="{roof}"/>'
    out += '<rect x="185" y="285" width="70" height="60" fill="#8fb3c9" stroke="#fff" stroke-width="5"/><rect x="345" y="285" width="70" height="60" fill="#8fb3c9" stroke="#fff" stroke-width="5"/><rect x="275" y="320" width="50" height="100" fill="#6b4a33"/><circle cx="315" cy="372" r="3" fill="#e8c27a"/>'
    out += '<path d="M300 420 L260 520 H340z" fill="#d9cbb0"/>'
    for x, r in ((70, 52), (530, 44), (110, 34)):
        out += f'<rect x="{x-4}" y="350" width="8" height="70" fill="#5a4636"/><circle cx="{x}" cy="{340}" r="{r}" fill="#4f7d46"/>'
    return out

