    out += '<rect y="400" width="600" height="120" fill="#b98a5e"/>' + ''.join(f'<line x1="{x}" y1="400" x2="{x-40}" y2="520" stroke="#a87b51" stroke-width="3"/>' for x in range(60, 680, 80))
    out += '<rect x="300" y="90" width="150" height="110" fill="#fff" stroke="#2b2b2b" stroke-width="6"/><path d="M310 190 L360 140 L395 170 L420 150 L440 190z" fill="#7fa38a"/>'
