    out += '<g transform="translate(205 150) rotate(-20)"><rect width="90" height="30" rx="8" fill="#e05b3a"/><rect x="40" y="30" width="8" height="70" fill="#2b2b2b"/><rect x="36" y="96" width="16" height="44" rx="5" fill="#2b2b2b"/></g>'
    return out

