    out = '<defs><linearGradient id="sk3" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#d7e6ee"/><stop offset="1" stop-color="#f6efe4"/></linearGradient></defs><rect width="600" height="520" fill="url(#sk3)"/>'
    out += '<path d="M0 360 Q300 320 600 360 V520 H0z" fill="#9dbb84"/>'
    for x, r in ((60, 60), (540, 54), (480, 36)):
        out += f'<rect x="{x-5}" y="300" width="10" height="80" fill="#5a4636"/><path d="M{x} {300-r*2} L{x+r*.8} 320 H{x-r*.8}z" fill="#3f6b45"/>'
