def art_dental(v=0):
    out = f'<rect width="600" height="520" fill="{["#dff2f4", "#e8f0fb", "#eef6ea"][v % 3]}"/><circle cx="300" cy="260" r="190" fill="#c4e8ec"/><circle cx="300" cy="260" r="140" fill="#fff" opacity=".6"/>'
    out += '<path d="M230 150 C190 150 180 200 190 240 C200 280 210 300 215 350 C220 395 250 400 262 360 C272 325 280 300 300 300 C320 300 328 325 338 360 C350 400 380 395 385 350 C390 300 400 280 410 240 C420 200 410 150 370 150 C340 150 330 168 300 168 C270 168 260 150 230 150z" fill="#fff" stroke="#0e9aa7" stroke-width="7"/>'
    out += '<path d="M240 190 q20 -14 40 0" fill="none" stroke="#0e9aa7" stroke-width="5" stroke-linecap="round" opacity=".5"/>'
    for x, y, s in ((440, 140, 1), (150, 380, .7), (460, 380, .8)):
        out += f'<path transform="translate({x} {y}) scale({s})" d="M0 -26 L7 -7 L26 0 L7 7 L0 26 L-7 7 L-26 0 L-7 -7z" fill="#0e9aa7"/>'
    return out

def art_land(v=0):
    slat = ["#7b5a3c", "#4b5560", "#8a6a48"][v % 3]
    out = '<defs><linearGradient id="sk4" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#cfe6f0"/><stop offset="1" stop-color="#eef3e6"/></linearGradient></defs><rect width="600" height="520" fill="url(#sk4)"/>'
    for x, r in ((90, 70), (250, 56), (520, 64)):
        out += f'<circle cx="{x}" cy="190" r="{r}" fill="#5f9150"/><circle cx="{x+30}" cy="215" r="{r*.7}" fill="#4f8045"/>'
    out += '<rect y="330" width="600" height="190" fill="#8cc06b"/>'
    out += ''.join(f'<rect x="{x}" y="230" width="20" height="120" fill="{slat}"/>' for x in range(0, 600, 24) if not 250 < x < 360)
    out += '<rect x="0" y="244" width="600" height="8" fill="#3d3d3d"/><rect x="0" y="320" width="600" height="8" fill="#3d3d3d"/>'
    out += '<rect x="262" y="226" width="92" height="128" fill="#3d3d3d"/><rect x="270" y="234" width="76" height="112" fill="#56606a"/>'
    out += '<path d="M280 350 L230 520 H390 L330 350z" fill="#d8ccb2"/>'
    for x in (90, 170, 440, 520):
        out += f'<ellipse cx="{x}" cy="372" rx="38" ry="22" fill="#4f8045"/>'
    out += '<circle cx="120" cy="440" r="7" fill="#f2c94c"/><circle cx="480" cy="460" r="7" fill="#e86f8a"/><circle cx="510" cy="430" r="7" fill="#f2c94c"/>'
    return out

