def page(c):
    art = ART[c["slug"]]
    opts = "".join(f'<div class="opt{" on" if i == 1 else ""}"><div class="pic">{ico(I[k])}</div><p>{t}</p></div>' for i, (k, t) in enumerate(c["opts"]))
    cards = "".join(f'''<article class="card"><div class="pic">{svg(art(i + 1))}<span class="tag">{tag}</span></div><div class="body"><h3>{n}</h3><dl><div><dt>{a[0]}</dt><dd>{a[1]}</dd></div><div><dt>{b[0]}</dt><dd>{b[1]}</dd></div></dl><div class="price"><b>{p}</b><span>Подробнее →</span></div></div></article>''' for i, (n, tag, a, b, p) in enumerate(c["cat"]))
    g = c["gift"]
    return f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=1440">
<meta name="robots" content="noindex, nofollow">
<title>{c["brand"]} — концепт Land Engine</title>
<link rel="stylesheet" href="concept.css"><style>:root{{{c["vars"]}}}</style></head>
<body>
<header><div class="w hd"><span class="logo"><i>{c["mark"]}</i>{c["brand"]}</span><nav class="nav">{"".join(f"<span>{n}</span>" for n in c["nav"])}</nav><span class="ph">{c["phone"]}<small>{c["hours"]}</small></span><a class="btn" href="#f">Заказать звонок</a></div></header>
<section class="hero"><div class="w"><div>
<span class="kick">{c["kick"]}</span><h1>{c["h1"]}</h1><p class="lead">{c["lead"]}</p>
<ul class="ticks">{"".join(f"<li>{t}</li>" for t in c["ticks"])}</ul>
<div class="acts"><a class="btn" href="#q">{c["cta"]}</a><a class="btn ghost" href="#c">{c["cta2"]}</a></div></div>
<div class="art">{svg(art(0))}<div class="float f1"><b>{c["f1"][0]}</b>{c["f1"][1]}</div><div class="float f2"><b>{c["f2"][0]}</b>{c["f2"][1]}</div></div></div></section>
<div class="w nums">{"".join(f"<div><b>{a}</b><span>{b}</span></div>" for a, b in c["nums"])}</div>
<section class="sec" id="q"><div class="w"><h2>{c["q_title"]}</h2><p class="sub">{c["q_sub"]}</p>
<div class="quiz"><div class="q-main"><div class="q-top"><span>Вопрос 2 из 5</span><span>40%</span></div><div class="q-bar"><i></i></div><h3>{c["q"]}</h3><div class="opts">{opts}</div><div class="q-nav"><span>← Назад</span><a class="btn" href="#q">Далее</a></div></div>
<aside class="q-side"><span class="gift">{ico(I["gift"]).replace("<svg", '<svg width="34" height="34"')}</span><h4>{g[0]}</h4><p>{g[1]}</p><ul>{"".join(f"<li>{x}</li>" for x in g[2])}</ul></aside></div></div></section>
<section class="sec tint" id="c"><div class="w"><h2>{c["cat_title"]}</h2><div class="cards">{cards}</div></div></section>
<section class="sec"><div class="w"><h2>Как мы работаем</h2><ol class="steps" style="list-style:none;padding:0">{"".join(f"<li><h3>{a}</h3><p>{b}</p></li>" for a, b in c["steps"])}</ol></div></section>
<section class="sec tint"><div class="w"><h2>Отзывы клиентов</h2><div class="revs">{"".join(f'<div class="rev"><span class="stars">★★★★★</span><p>«{t}»</p><span class="who"><i>{n[0]}</i><span>{n}<small>{s}</small></span></span></div>' for t, n, s in c["revs"])}</div></div></section>
<section class="final sec" id="f" style="padding-bottom:96px"><div class="w final-box"><div><h2>{c["final"]}</h2><p>{c["final_sub"]}</p></div>
<div class="form"><span class="inp">Ваше имя</span><span class="inp">+7 (___) ___-__-__</span><a class="btn" href="#f">{c["btn"]}</a><small>Нажимая кнопку, вы соглашаетесь с политикой конфиденциальности</small></div></div></section>
<footer class="ft"><div class="w"><span class="logo"><i>{c["mark"]}</i>{c["brand"]}</span><span>{c["phone"]} · Концепт сайта от Land Engine</span></div></footer>
</body></html>
'''

for c in C:
    (OUT / f'{c["slug"]}.html').write_text(page(c), encoding="utf-8")
print("built", len(C))
